class CancellationNotificationTest {

    record Mail(String address, String subject, String body) {
    }

    @Configuration
    static class RecordingMail {

        final List<Mail> sent = new ArrayList<>();

        @Bean
        @Primary
        MailTransport recordingTransport() {
            return (address, subject, body) -> sent.add(new Mail(address, subject, body));
        }
    }

    @Test
    void cancellingAnOrderMailsTheCustomerOnce() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, RecordingMail.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            CustomerFacade customers = shop.getBean(CustomerFacade.class);
            List<Mail> sent = shop.getBean(RecordingMail.class).sent;

            customers.register("c-7", "anna@example.com");
            String id = orders.place("c-7", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, sent.size());
            assertEquals("anna@example.com", sent.get(0).address());
            assertTrue(sent.get(0).subject().contains(id));
        }
    }

    @Test
    void noMailWhenTheCancelledOrdersCustomerHasNoAddress() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class, RecordingMail.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            List<Mail> sent = shop.getBean(RecordingMail.class).sent;

            String id = orders.place("c-unknown", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);

            assertEquals(0, sent.size());
        }
    }
}
}

