    private static AnnotationConfigApplicationContext startShop(List<Mail> sent) {
        var shop = new AnnotationConfigApplicationContext();
        shop.register(ShopConfig.class);
        shop.registerBean(MailTransport.class,
                () -> (address, subject, body) -> sent.add(new Mail(address, subject, body)),
                bd -> bd.setPrimary(true));
        shop.refresh();
        return shop;
