            OrderFacade orders = shop.getBean(OrderFacade.class);
            CustomerFacade customers = shop.getBean(CustomerFacade.class);

            customers.register("c-7", "anna@example.com");
            String id = orders.place("c-7", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, sent.size());
            assertEquals("anna@example.com", sent.get(0).address());
            assertTrue(sent.get(0).subject().contains(id));
